//! G14 local compatibility and acceptance guard.
//!
//! This is an independent test target. It consumes the descriptor bytes
//! generated by `erpx-proto`, round-trips the real generated directory/PITR
//! messages, and inspects the real mobile and physical-PITR boundaries. It
//! never starts a vendor, device, database, object store, or restore process.
//! Missing external evidence is reported as a blocker; it is never replaced
//! with a fake provider, mock response, or schema-only fixture.

use std::{
    collections::{BTreeMap, BTreeSet},
    env, fs,
    path::PathBuf,
};

use erpx_proto::{
    FILE_DESCRIPTOR_SET,
    common::{ActorAttribution, CommandContext},
    erpx::{
        identity_access::DirectoryConnectorSummary,
        platform_administration::{PitrRecoveryPoint, ScheduleHoldingBackupRequest},
    },
};
use prost::Message;
use prost_types::{
    DescriptorProto, EnumDescriptorProto, FieldDescriptorProto, FileDescriptorProto,
    FileDescriptorSet,
};

