const APPROVED_DESCRIPTOR_ENV: &str = "ERPX_G14_APPROVED_PROTO_DESCRIPTOR";
const APPROVED_DESCRIPTOR_SHA256_ENV: &str = "ERPX_G14_APPROVED_PROTO_DESCRIPTOR_SHA256";

#[derive(Debug, Clone, PartialEq, Eq)]
struct ApprovedDescriptorReference {
    canonical_path: PathBuf,
    sha256: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FieldContract {
    name: String,
    number: i32,
    label: i32,
    field_type: i32,
    type_name: String,
    json_name: String,
    oneof_index: Option<i32>,
    proto3_optional: bool,
}

#[derive(Debug, Default)]
struct DescriptorInventory {
    messages: BTreeMap<String, MessageContract>,
    enums: BTreeMap<String, EnumContract>,
    services: BTreeMap<String, BTreeMap<String, MethodContract>>,
}

#[derive(Debug, Default)]
struct MessageContract {
    fields: BTreeMap<i32, FieldContract>,
    reserved_ranges: BTreeSet<(i32, i32)>,
    reserved_names: BTreeSet<String>,
}

#[derive(Debug, Default)]
struct EnumContract {
    values: BTreeMap<i32, String>,
    reserved_ranges: BTreeSet<(i32, i32)>,
    reserved_names: BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MethodContract {
    input_type: String,
    output_type: String,
    client_streaming: bool,
    server_streaming: bool,
}

fn qualified_name(prefix: &str, name: &str) -> String {
    if prefix.is_empty() {
        name.to_owned()
    } else {
        format!("{prefix}.{name}")
    }
}

fn add_message_contract(
    message: &DescriptorProto,
    prefix: &str,
    inventory: &mut DescriptorInventory,
) {
    let Some(name) = message.name.as_deref() else {
        return;
    };
    let full_name = qualified_name(prefix, name);
    let fields = message
        .field
        .iter()
        .filter_map(|field| {
            let number = field.number?;
            let field_name = field.name.clone()?;
            Some((
                number,
                FieldContract {
                    name: field_name,
                    number,
                    label: field.label.unwrap_or_default(),
                    field_type: field.r#type.unwrap_or_default(),
                    type_name: field.type_name.clone().unwrap_or_default(),
                    json_name: field.json_name.clone().unwrap_or_default(),
                    oneof_index: field.oneof_index,
                    proto3_optional: field.proto3_optional.unwrap_or(false),
                },
            ))
        })
        .collect();
    let reserved_ranges = message
        .reserved_range
        .iter()
        .filter_map(|range| Some((range.start?, range.end?)))
        .collect();
    let reserved_names = message.reserved_name.iter().cloned().collect();
    assert!(
        inventory
            .messages
            .insert(
                full_name.clone(),
                MessageContract {
                    fields,
                    reserved_ranges,
                    reserved_names,
                },
            )
            .is_none(),
        "descriptor contains a duplicate message: {full_name}"
    );
    for nested in &message.nested_type {
        add_message_contract(nested, &full_name, inventory);
    }
    for enum_type in &message.enum_type {
        add_enum_contract(enum_type, &full_name, inventory);
    }
}

fn add_enum_contract(
    enum_type: &EnumDescriptorProto,
    prefix: &str,
    inventory: &mut DescriptorInventory,
) {
    let Some(name) = enum_type.name.as_deref() else {
        return;
    };
    let full_name = qualified_name(prefix, name);
    let values = enum_type
        .value
        .iter()
        .filter_map(|value| Some((value.number?, value.name.clone()?)))
        .collect();
    let reserved_ranges = enum_type
        .reserved_range
        .iter()
        .filter_map(|range| Some((range.start?, range.end?)))
        .collect();
    let reserved_names = enum_type.reserved_name.iter().cloned().collect();
    assert!(
        inventory
            .enums
            .insert(
                full_name.clone(),
                EnumContract {
                    values,
                    reserved_ranges,
                    reserved_names,
                },
            )
            .is_none(),
        "descriptor contains a duplicate enum: {full_name}"
    );
}

fn descriptor_inventory(set: &FileDescriptorSet) -> DescriptorInventory {
    let mut inventory = DescriptorInventory::default();
    for file in &set.file {
        let package = file.package.as_deref().unwrap_or_default();
        for message in &file.message_type {
            add_message_contract(message, package, &mut inventory);
        }
        for enum_type in &file.enum_type {
            add_enum_contract(enum_type, package, &mut inventory);
        }
        for service in &file.service {
            let Some(name) = service.name.as_deref() else {
                continue;
            };
            let full_name = qualified_name(package, name);
            let mut method_names = BTreeSet::new();
            let methods = service
                .method
                .iter()
                .filter_map(|method| {
                    let method_name = method.name.clone()?;
                    assert!(
                        method_names.insert(method_name.clone()),
                        "descriptor contains a duplicate method: {full_name}.{method_name}"
                    );
                    Some((
                        method_name,
                        MethodContract {
                            input_type: method.input_type.clone().unwrap_or_default(),
                            output_type: method.output_type.clone().unwrap_or_default(),
                            client_streaming: method.client_streaming.unwrap_or(false),
                            server_streaming: method.server_streaming.unwrap_or(false),
                        },
                    ))
                })
                .collect();
            assert!(
                inventory
                    .services
                    .insert(full_name.clone(), methods)
                    .is_none(),
                "descriptor contains a duplicate service: {full_name}"
            );
        }
    }
    inventory
}

fn normalize_type_name(name: &str) -> &str {
    name.trim_start_matches('.')
}

fn require_markers(surface: &str, name: &str, markers: &[&str]) {
    for marker in markers {
        assert!(
            surface.contains(marker),
            "G14 local compatibility marker missing from {name}: {marker}"
        );
    }
}

fn require_ordered_markers(surface: &str, name: &str, markers: &[&str]) {
    let mut cursor = 0;
    for marker in markers {
        let Some(relative) = surface[cursor..].find(marker) else {
            panic!(
                "G14 local compatibility marker missing from {name} after byte {cursor}: {marker}"
            );
        };
        cursor += relative + marker.len();
    }
}

fn current_descriptor() -> FileDescriptorSet {
    FileDescriptorSet::decode(FILE_DESCRIPTOR_SET)
        .expect("the generated ERPX protobuf descriptor set must decode")
}

fn assert_descriptor_is_self_consistent(set: &FileDescriptorSet) {
    assert!(
        !set.file.is_empty(),
        "generated descriptor set must not be empty"
    );
    let mut file_names = BTreeSet::new();
    let inventory = descriptor_inventory(set);
    let message_names = inventory
        .messages
        .keys()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let enum_names = inventory
        .enums
        .keys()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();

    for file in &set.file {
        let file_name = file.name.as_deref().expect("descriptor file name");
        assert!(
            file_names.insert(file_name),
            "generated descriptor contains a duplicate file: {file_name}"
        );
        for message in &file.message_type {
            assert_message_is_well_formed(message, file.package.as_deref().unwrap_or_default());
        }
        for enum_type in &file.enum_type {
            assert_enum_is_well_formed(enum_type, file.package.as_deref().unwrap_or_default());
        }
        for service in &file.service {
            for method in &service.method {
                let input = method
                    .input_type
                    .as_deref()
                    .map(normalize_type_name)
                    .expect("RPC input type");
                let output = method
                    .output_type
                    .as_deref()
                    .map(normalize_type_name)
                    .expect("RPC output type");
                assert!(
                    message_names.contains(input),
                    "RPC input type is not defined: {input}"
                );
                assert!(
                    message_names.contains(output),
                    "RPC output type is not defined: {output}"
                );
            }
        }
    }

    for message in inventory.messages.values() {
        for field in message.fields.values() {
            if matches!(field.field_type, 11 | 14) {
                let reference = normalize_type_name(&field.type_name);
                assert!(
                    message_names.contains(reference) || enum_names.contains(reference),
                    "field type is not defined: {reference}"
                );
            }
            if let Some(oneof_index) = field.oneof_index {
                assert!(oneof_index >= 0, "oneof index must not be negative");
            }
        }
    }
}

fn assert_message_is_well_formed(message: &DescriptorProto, prefix: &str) {
    let name = message
        .name
        .as_deref()
        .map(|name| qualified_name(prefix, name))
        .unwrap_or_else(|| format!("{prefix}.<unnamed>"));
    let mut field_numbers = BTreeSet::new();
    let mut field_names = BTreeSet::new();
    for field in &message.field {
        let number = field.number.expect("message field number");
        let field_name = field.name.as_deref().expect("message field name");
        assert!(
            field_numbers.insert(number),
            "message contains duplicate field number: {name}.{number}"
        );
        assert!(
            field_names.insert(field_name),
            "message contains duplicate field name: {name}.{field_name}"
        );
        assert!(
            (1..=536_870_911).contains(&number),
            "field number is invalid"
        );
        for reserved_range in &message.reserved_range {
            let start = reserved_range.start.expect("reserved range start");
            let end = reserved_range.end.expect("reserved range end");
            assert!(
                !(start <= number && number < end),
                "message field reuses a reserved number: {name}.{number}"
            );
        }
        if let Some(oneof_index) = field.oneof_index {
            assert!(
                usize::try_from(oneof_index).is_ok_and(|index| index < message.oneof_decl.len()),
                "field oneof index is out of bounds: {name}.{number}"
            );
        }
    }
    for nested in &message.nested_type {
        assert_message_is_well_formed(nested, &name);
    }
    for enum_type in &message.enum_type {
        assert_enum_is_well_formed(enum_type, &name);
    }
}

fn assert_enum_is_well_formed(enum_type: &EnumDescriptorProto, prefix: &str) {
    let name = enum_type
        .name
        .as_deref()
        .map(|name| qualified_name(prefix, name))
        .unwrap_or_else(|| format!("{prefix}.<unnamed>"));
    let mut value_numbers = BTreeSet::new();
    let mut value_names = BTreeSet::new();
    for value in &enum_type.value {
        let number = value.number.expect("enum value number");
        let value_name = value.name.as_deref().expect("enum value name");
        assert!(
            value_numbers.insert(number),
            "enum contains duplicate value number: {name}.{number}"
        );
        assert!(
            value_names.insert(value_name),
            "enum contains duplicate value name: {name}.{value_name}"
        );
    }
}

fn collect_descriptor_names(set: &FileDescriptorSet) -> Result<(), String> {
    if set.file.is_empty() {
        return Err("descriptor baseline is empty".into());
    }

    let mut file_names = BTreeSet::new();
    let mut message_names = BTreeSet::new();
    let mut enum_names = BTreeSet::new();
    let mut service_names = BTreeSet::new();
    for file in &set.file {
        let file_name = file
            .name
            .as_deref()
            .filter(|name| !name.is_empty())
            .ok_or_else(|| "descriptor file name is missing".to_owned())?;
        if !file_names.insert(file_name) {
            return Err(format!("descriptor contains a duplicate file: {file_name}"));
        }
        let package = file.package.as_deref().unwrap_or_default();
        for message in &file.message_type {
            collect_message_names(message, package, &mut message_names, &mut enum_names)?;
        }
        for enum_type in &file.enum_type {
            collect_enum_name(enum_type, package, &mut enum_names)?;
        }
        for service in &file.service {
            let name = service
                .name
                .as_deref()
                .filter(|name| !name.is_empty())
                .ok_or_else(|| "descriptor service name is missing".to_owned())?;
            let full_name = qualified_name(package, name);
            if !service_names.insert(full_name.clone()) {
                return Err(format!(
                    "descriptor contains a duplicate service: {full_name}"
                ));
            }
            let mut method_names = BTreeSet::new();
            for method in &service.method {
                let method_name = method
                    .name
                    .as_deref()
                    .filter(|name| !name.is_empty())
                    .ok_or_else(|| format!("descriptor method name is missing: {full_name}"))?;
                if !method_names.insert(method_name) {
                    return Err(format!(
                        "descriptor contains a duplicate method: {full_name}.{method_name}"
                    ));
                }
            }
        }
    }
    if message_names.is_empty() && enum_names.is_empty() && service_names.is_empty() {
        return Err("descriptor baseline contains no declarations".into());
    }
    Ok(())
}

fn collect_message_names(
    message: &DescriptorProto,
    prefix: &str,
    message_names: &mut BTreeSet<String>,
    enum_names: &mut BTreeSet<String>,
) -> Result<(), String> {
    let name = message
        .name
        .as_deref()
        .filter(|name| !name.is_empty())
        .ok_or_else(|| "descriptor message name is missing".to_owned())?;
    let full_name = qualified_name(prefix, name);
    if !message_names.insert(full_name.clone()) {
        return Err(format!(
            "descriptor contains a duplicate message: {full_name}"
        ));
    }
    let mut field_numbers = BTreeSet::new();
    let mut field_names = BTreeSet::new();
    for field in &message.field {
        let number = field
            .number
            .ok_or_else(|| format!("descriptor field number is missing: {full_name}"))?;
        let field_name = field
            .name
            .as_deref()
            .filter(|name| !name.is_empty())
            .ok_or_else(|| format!("descriptor field name is missing: {full_name}"))?;
        if !field_numbers.insert(number) {
            return Err(format!(
                "descriptor contains a duplicate field number: {full_name}.{number}"
            ));
        }
        if !field_names.insert(field_name) {
            return Err(format!(
                "descriptor contains a duplicate field name: {full_name}.{field_name}"
            ));
        }
        if !(1..=536_870_911).contains(&number) {
            return Err(format!(
                "descriptor contains an invalid field number: {full_name}.{number}"
            ));
        }
    }
    for reserved in &message.reserved_range {
        let start = reserved
            .start
            .ok_or_else(|| format!("descriptor reserved range start is missing: {full_name}"))?;
        let end = reserved
            .end
            .ok_or_else(|| format!("descriptor reserved range end is missing: {full_name}"))?;
        if start >= end {
            return Err(format!("descriptor reserved range is invalid: {full_name}"));
        }
        if field_numbers
            .iter()
            .any(|number| start <= *number && *number < end)
        {
            return Err(format!(
                "descriptor reuses a reserved field number: {full_name}"
            ));
        }
    }
    for nested in &message.nested_type {
        collect_message_names(nested, &full_name, message_names, enum_names)?;
    }
    for enum_type in &message.enum_type {
        collect_enum_name(enum_type, &full_name, enum_names)?;
    }
    Ok(())
}

fn collect_enum_name(
    enum_type: &EnumDescriptorProto,
    prefix: &str,
    enum_names: &mut BTreeSet<String>,
) -> Result<(), String> {
    let name = enum_type
        .name
        .as_deref()
        .filter(|name| !name.is_empty())
        .ok_or_else(|| "descriptor enum name is missing".to_owned())?;
    let full_name = qualified_name(prefix, name);
    if !enum_names.insert(full_name.clone()) {
        return Err(format!("descriptor contains a duplicate enum: {full_name}"));
    }
    let mut value_numbers = BTreeSet::new();
    let mut value_names = BTreeSet::new();
    for value in &enum_type.value {
        let value_name = value
            .name
            .as_deref()
            .filter(|name| !name.is_empty())
            .ok_or_else(|| format!("descriptor enum value name is missing: {full_name}"))?;
        let number = value
            .number
            .ok_or_else(|| format!("descriptor enum value number is missing: {full_name}"))?;
        if !value_numbers.insert(number) {
            return Err(format!(
                "descriptor contains a duplicate enum value number: {full_name}.{number}"
            ));
        }
        if !value_names.insert(value_name) {
            return Err(format!(
                "descriptor contains a duplicate enum value name: {full_name}.{value_name}"
            ));
        }
    }
    for reserved in &enum_type.reserved_range {
        let start = reserved.start.ok_or_else(|| {
            format!("descriptor enum reserved range start is missing: {full_name}")
        })?;
        let end = reserved
            .end
            .ok_or_else(|| format!("descriptor enum reserved range end is missing: {full_name}"))?;
        // EnumDescriptorProto uses inclusive range endpoints, unlike message
        // reserved ranges whose end is exclusive. A single reserved enum value
        // is therefore encoded as start == end.
        if start > end {
            return Err(format!(
                "descriptor enum reserved range is invalid: {full_name}"
            ));
        }
        if value_numbers
            .iter()
            .any(|number| start <= *number && *number <= end)
        {
            return Err(format!(
                "descriptor reuses a reserved enum value: {full_name}"
            ));
        }
    }
    Ok(())
}

fn compare_approved_descriptor(approved_bytes: &[u8], current_bytes: &[u8]) -> Result<(), String> {
    let approved = FileDescriptorSet::decode(approved_bytes)
        .map_err(|error| format!("approved protobuf descriptor is invalid: {error}"))?;
    let current = FileDescriptorSet::decode(current_bytes)
        .map_err(|error| format!("current protobuf descriptor is invalid: {error}"))?;
    collect_descriptor_names(&approved)?;
    collect_descriptor_names(&current)?;
    let approved = descriptor_inventory(&approved);
    let current = descriptor_inventory(&current);

    for (message_name, expected) in approved.messages {
        let actual = current
            .messages
            .get(&message_name)
            .ok_or_else(|| format!("approved message was removed: {message_name}"))?;
        for (number, expected_field) in expected.fields {
            let actual_field = actual
                .fields
                .get(&number)
                .ok_or_else(|| format!("approved field was removed: {message_name}.{number}"))?;
            if actual_field != &expected_field {
                return Err(format!(
                    "approved field changed incompatibly: {message_name}.{number}"
                ));
            }
        }
        if !expected.reserved_ranges.is_subset(&actual.reserved_ranges) {
            return Err(format!(
                "approved message reserved range was removed: {message_name}"
            ));
        }
        if !expected.reserved_names.is_subset(&actual.reserved_names) {
            return Err(format!(
                "approved message reserved name was removed: {message_name}"
            ));
        }
    }
    for (enum_name, expected) in approved.enums {
        let actual = current
            .enums
            .get(&enum_name)
            .ok_or_else(|| format!("approved enum was removed: {enum_name}"))?;
        for (number, expected_name) in expected.values {
            let actual_name = actual
                .values
                .get(&number)
                .ok_or_else(|| format!("approved enum value was removed: {enum_name}.{number}"))?;
            if actual_name != &expected_name {
                return Err(format!(
                    "approved enum value changed incompatibly: {enum_name}.{number}"
                ));
            }
        }
        if !expected.reserved_ranges.is_subset(&actual.reserved_ranges) {
            return Err(format!(
                "approved enum reserved range was removed: {enum_name}"
            ));
        }
        if !expected.reserved_names.is_subset(&actual.reserved_names) {
            return Err(format!(
                "approved enum reserved name was removed: {enum_name}"
            ));
        }
    }
    for (service_name, expected_methods) in approved.services {
        let actual_methods = current
            .services
            .get(&service_name)
            .ok_or_else(|| format!("approved service was removed: {service_name}"))?;
        for (method_name, expected) in expected_methods {
            let actual = actual_methods.get(&method_name).ok_or_else(|| {
                format!("approved RPC method was removed: {service_name}.{method_name}")
            })?;
            if actual != &expected {
                return Err(format!(
                    "approved RPC method changed incompatibly: {service_name}.{method_name}"
                ));
            }
        }
    }
    Ok(())
}

fn approved_descriptor_reference() -> Option<ApprovedDescriptorReference> {
    let path = env::var(APPROVED_DESCRIPTOR_ENV).ok();
    let sha256 = env::var(APPROVED_DESCRIPTOR_SHA256_ENV).ok();
    match (path, sha256) {
        (None, None) => None,
        (Some(_), None) | (None, Some(_)) => panic!(
            "{APPROVED_DESCRIPTOR_ENV} and {APPROVED_DESCRIPTOR_SHA256_ENV} must be supplied together"
        ),
        (Some(path), Some(sha256)) => {
            if path.trim().is_empty() || path.chars().any(char::is_control) {
                panic!("{APPROVED_DESCRIPTOR_ENV} must be a non-empty safe path when set");
            }
            let path = PathBuf::from(path);
            assert!(
                path.is_absolute(),
                "{APPROVED_DESCRIPTOR_ENV} must be an absolute path so descriptor provenance is unambiguous"
            );
            let file_type = fs::symlink_metadata(&path).unwrap_or_else(|error| {
                panic!(
                    "{APPROVED_DESCRIPTOR_ENV} must point to an existing regular file: {}: {error}",
                    path.display()
                )
            });
            assert!(
                file_type.file_type().is_file(),
                "{APPROVED_DESCRIPTOR_ENV} must point directly to a regular file; symlinks and directories are not accepted: {}",
                path.display()
            );
            assert!(
                file_type.len() > 0,
                "{APPROVED_DESCRIPTOR_ENV} must point to a non-empty descriptor file: {}",
                path.display()
            );
            let canonical_path = fs::canonicalize(&path).unwrap_or_else(|error| {
                panic!(
                    "{APPROVED_DESCRIPTOR_ENV} could not be canonicalized: {}: {error}",
                    path.display()
                )
            });
            assert!(
                sha256.len() == 64 && sha256.bytes().all(|byte| byte.is_ascii_hexdigit()),
                "{APPROVED_DESCRIPTOR_SHA256_ENV} must be exactly 64 hexadecimal characters"
            );
            assert!(
                sha256.bytes().all(|byte| !byte.is_ascii_uppercase()),
                "{APPROVED_DESCRIPTOR_SHA256_ENV} must use lowercase hexadecimal characters"
            );
            Some(ApprovedDescriptorReference {
                canonical_path,
                sha256,
            })
        }
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    const INITIAL_STATE: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    const ROUND_CONSTANTS: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];

    let bit_len = (bytes.len() as u64).wrapping_mul(8);
    let mut padded = Vec::with_capacity(bytes.len() + 72);
    padded.extend_from_slice(bytes);
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());

    let mut state = INITIAL_STATE;
    for chunk in padded.chunks_exact(64) {
        let mut schedule = [0_u32; 64];
        for (index, word) in schedule.iter_mut().take(16).enumerate() {
            let start = index * 4;
            *word = u32::from_be_bytes([
                chunk[start],
                chunk[start + 1],
                chunk[start + 2],
                chunk[start + 3],
            ]);
        }
        for index in 16..64 {
            let x = schedule[index - 15];
            let y = schedule[index - 2];
            let small_sigma0 = x.rotate_right(7) ^ x.rotate_right(18) ^ (x >> 3);
            let small_sigma1 = y.rotate_right(17) ^ y.rotate_right(19) ^ (y >> 10);
            schedule[index] = schedule[index - 16]
                .wrapping_add(small_sigma0)
                .wrapping_add(schedule[index - 7])
                .wrapping_add(small_sigma1);
        }

        let mut working = state;
        for index in 0..64 {
            let [a, b, c, d, e, f, g, h] = working;
            let big_sigma0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let big_sigma1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let choice = (e & f) ^ ((!e) & g);
            let majority = (a & b) ^ (a & c) ^ (b & c);
            let temp1 = h
                .wrapping_add(big_sigma1)
                .wrapping_add(choice)
                .wrapping_add(ROUND_CONSTANTS[index])
                .wrapping_add(schedule[index]);
            let temp2 = big_sigma0.wrapping_add(majority);
            working = [
                temp1.wrapping_add(temp2),
                a,
                b,
                c,
                d.wrapping_add(temp1),
                e,
                f,
                g,
            ];
        }
        for (current, round) in state.iter_mut().zip(working) {
            *current = current.wrapping_add(round);
        }
    }

    state.iter().map(|word| format!("{word:08x}")).collect()
}

#[test]
fn g14_generated_descriptor_is_self_consistent_and_g14_fields_are_wire_stable() {
    let set = current_descriptor();
    assert_descriptor_is_self_consistent(&set);

    let names = set
        .file
        .iter()
        .filter_map(|file| file.name.as_deref())
        .collect::<BTreeSet<_>>();
    assert!(names.contains("erpx/interface/reference.proto"));
    assert!(names.contains("erpx/catalog/active.proto"));
    assert!(names.contains("erpx/common/context.proto"));
    assert!(!names.contains("erpx/platform/platform.proto"));

    let inventory = descriptor_inventory(&set);
    let resolve = inventory
        .messages
        .get("erpx.interface.ResolveReferenceRequest")
        .expect("stable reference request must be generated");
    for (number, name) in [(1, "record_id"), (2, "authority_scope"), (3, "purpose")] {
        assert_eq!(
            resolve.fields.get(&number).map(|field| field.name.as_str()),
            Some(name),
            "reference field number changed for {name}"
        );
    }

    let reference_service = inventory
        .services
        .get("erpx.reference.ReferenceQueryService")
        .expect("reference query service must be active");
    assert!(reference_service.contains_key("Resolve"));
    assert!(reference_service.contains_key("Search"));
    assert!(reference_service.contains_key("ListBacklinks"));
    let collaboration_service = inventory
        .services
        .get("erpx.collaboration.CollaborationCommandService")
        .expect("collaboration command service must be active");
    assert!(collaboration_service.contains_key("CreateThread"));
    assert!(collaboration_service.contains_key("AddComment"));
    assert!(
        inventory
            .services
            .keys()
            .all(|service| !service.starts_with("erpx.platform."))
    );
}

